import { MouseEvent } from 'react';

import { Plus } from 'components/icon';
import { TextButton } from 'components/UI';

interface ResetFilterButtonProps {
  onResetFilter: () => void;
  dataTestId?: string;
}

export const ResetFilterButton = ({
  onResetFilter,
  dataTestId,
}: ResetFilterButtonProps) => {
  const handleClick = (event: MouseEvent) => {
    event.preventDefault();
    onResetFilter();
  };

  return (
    <TextButton
      data-testid={dataTestId ? `reset-filter-button-${dataTestId}` : undefined}
      size="medium"
      style={{ color: '#0363c4', minWidth: 'fit-content' }}
      onClick={handleClick}
    >
      <Plus
        data-testid={
          dataTestId ? `reset-filter-button-icon-${dataTestId}` : undefined
        }
        size="large"
        style={{
          transform: 'rotate(45deg)',
          marginRight: '5px',
          width: '20px',
        }}
      />
      Reset filter
    </TextButton>
  );
};
